/* ===================== HELPERS ===================== */
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const ic=(n,c='')=>`<svg class="ico ${c}"><use href="#${n}"/></svg>`;
const km=(l,u=S.uni)=>{const U=UNIS[u];return Math.round(Math.hypot(l.x-U.x,l.y-U.y)/62*10)/10;};
const busMin=d=>d<0.9?Math.round(d*13):Math.round(d*5+6);
const how=d=>d<0.9?`${busMin(d)} min caminando`:`${busMin(d)} min en bus`;
function fair(p,b=S.budget){ if(p<=b) return {k:'good',l:'Dentro de tu presupuesto',s:'Justo para ti'}; if(p<=b*1.15) return {k:'mid',l:'Un poco sobre tu presupuesto',s:'Algo alto para ti'}; return {k:'bad',l:'Caro para tu presupuesto',s:'Caro para ti'}; }
function zfair(p,z){const a=ZAVG[z]||190; if(p<=a*0.97) return {k:'good',s:'Bajo el promedio de la zona',l:`Precio justo: el promedio en ${z} es $${a}`}; if(p<=a*1.1) return {k:'mid',s:'En el promedio de la zona',l:`Cerca del promedio de ${z} ($${a})`}; return {k:'bad',s:'Sobre el promedio de la zona',l:`Sobre el promedio de ${z} ($${a}); a los estudiantes les aparecerá como caro para la zona`}; }
function safety(z){const s=ZSAFE[z]||{s:3.5,l:'Media',upc:'UPC cercana',r:'Pocos reportes'};const k=s.s>=4?'good':s.s>=3.2?'mid':'bad';return {...s,k,lab:k==='good'?'Zona segura':k==='mid'?'Precaución moderada':'Precaución de noche'};}
function cost(l){const d=km(l);const bus=d<0.9?0:0.30*2*22;const items=[['Arriendo',l.price]];Object.entries(EXTRA).forEach(([k,v])=>{if(!l.sv.includes(k))items.push([SVC[k][0]+' (no incluido, estimado)',v]);});if(bus)items.push(['Pasajes de bus (22 días de clase)',bus]);return {items,tot:Math.round(items.reduce((a,[,v])=>a+v,0)),bus};}
const money=v=>'$'+(v%1?v.toFixed(2):v);
function rating(l){const r=REV[l.id];if(!r||!r.length)return null;const n=r.length;return {n,avg:Math.round(r.reduce((a,x)=>a+x.r,0)/n*10)/10,a:[0,1,2,3].map(i=>r.reduce((s2,x)=>s2+x.a[i],0)/n)};}
const stars=(v,c='xs')=>`<span class="stars">${[1,2,3,4,5].map(i=>`<svg class="ico ${c} ${i<=Math.round(v)?'':'off'}"><use href="#i-star"/></svg>`).join('')}</span>`;
function agentOf(l){if(l.ag==='me'){const n=S.user?.name||'Tú';return {n,ini:initials(n).toUpperCase(),col:'#0469E6',v:S.verif==='ok',r:0,rv:0,ph:'—'};}return AGENTS[l.ag];}
const thumb=l=>l.img?`<img src="${l.img}" style="width:100%;height:100%;object-fit:cover" alt="">`:room('cuarto',l.pal);
const countFor=(u,b)=>visible().filter(l=>l.price<=b&&km(l,u)<=4).length;
const visible=()=>L.filter(l=>l.st);
function toast(m){const t=$('#toast');t.querySelector('span').textContent=m;t.classList.add('on');clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('on'),2600);}
function modal(html,wide){$('#modal').className='modal'+(wide?' wide':'');$('#modal').innerHTML=html;$('#ov').classList.add('on');}
function closeModal(){$('#ov').classList.remove('on');}
$('#ov').addEventListener('click',e=>{if(e.target.id==='ov')closeModal();});
function store(){try{localStorage.setItem('nidu',JSON.stringify({user:S.user,uni:S.uni,budget:S.budget,fav:[...S.fav],orig:S.orig,verif:S.verif,prof:S.prof,subscribed:S.subscribed,preview:S.preview,friends:[...S.friends]}));}catch(e){}}
try{const d=JSON.parse(localStorage.getItem('nidu')||'null');if(d){S.user=d.user;S.uni=d.uni||'espol';S.budget=d.budget||180;S.fav=new Set(d.fav||[]);S.orig=d.orig||'milagro';S.verif=d.verif||null;if(S.verif==='rev')S.verif='ok';S.prof=!!d.prof;S.subscribed=!!d.subscribed;S.preview=!!d.preview;if(Array.isArray(d.friends))S.friends=new Set(d.friends);}}catch(e){}

